import { createHash } from 'node:crypto';
import type {
  CallerAgentKind,
  WorkItemInitiator,
} from '../types/change-request-types';

export const CALLER_AGENT_ALLOWLIST = [
  'claude',
  'codex',
  'cursor',
  'grokbot',
] as const;

export type CallerHandoff = {
  agent: CallerAgentKind;
  model?: string;
  session?: string;
};

export type { CallerAgentKind, WorkItemInitiator };

export const HANDOFF_ENV_VARS = {
  agent: 'RIVET_CALLER_AGENT',
  model: 'RIVET_CALLER_MODEL',
  session: 'RIVET_CALLER_SESSION',
} as const;

export type HandoffFlagValues = {
  callerAgent?: string;
  callerModel?: string;
  callerSession?: string;
  handoffJson?: string;
};

const normalizeAgentKind = (raw: string): CallerAgentKind => {
  const candidate = raw.trim().toLowerCase();
  return (CALLER_AGENT_ALLOWLIST as readonly string[]).includes(candidate)
    ? (candidate as CallerAgentKind)
    : 'unknown';
};

const nonEmpty = (value: string | undefined): string | undefined => {
  const trimmed = value?.trim();
  return trimmed ? trimmed : undefined;
};

type HandoffJsonShape = {
  agent?: unknown;
  model?: unknown;
  session?: unknown;
};

const parseHandoffJson = (
  raw: string,
): { agent?: string; model?: string; session?: string } | null => {
  try {
    const parsed = JSON.parse(raw) as HandoffJsonShape;
    if (typeof parsed !== 'object' || parsed === null) {
      return null;
    }
    return {
      agent: typeof parsed.agent === 'string' ? parsed.agent : undefined,
      model: typeof parsed.model === 'string' ? parsed.model : undefined,
      session: typeof parsed.session === 'string' ? parsed.session : undefined,
    };
  } catch {
    return null;
  }
};

export type ParseHandoffResult =
  { ok: true; handoff: CallerHandoff | null } | { ok: false; error: string };

export const parseHandoff = (
  flags: HandoffFlagValues,
  env: NodeJS.ProcessEnv = process.env,
): ParseHandoffResult => {
  let fromJson: { agent?: string; model?: string; session?: string } = {};
  if (flags.handoffJson !== undefined) {
    const parsed = parseHandoffJson(flags.handoffJson);
    if (!parsed) {
      return {
        ok: false,
        error:
          '--handoff must be a JSON object like {"agent":"claude","model":"...","session":"..."}',
      };
    }
    fromJson = parsed;
  }

  const agentRaw =
    nonEmpty(flags.callerAgent) ??
    nonEmpty(fromJson.agent) ??
    nonEmpty(env[HANDOFF_ENV_VARS.agent]);
  const model =
    nonEmpty(flags.callerModel) ??
    nonEmpty(fromJson.model) ??
    nonEmpty(env[HANDOFF_ENV_VARS.model]);
  const session =
    nonEmpty(flags.callerSession) ??
    nonEmpty(fromJson.session) ??
    nonEmpty(env[HANDOFF_ENV_VARS.session]);

  if (!agentRaw && !model && !session) {
    return { ok: true, handoff: null };
  }

  return {
    ok: true,
    handoff: {
      agent: agentRaw ? normalizeAgentKind(agentRaw) : 'unknown',
      ...(model ? { model } : {}),
      ...(session ? { session } : {}),
    },
  };
};

const ENV_MARKERS_BY_AGENT: ReadonlyArray<
  readonly [CallerAgentKind, readonly string[]]
> = [
  ['claude', ['CLAUDECODE', 'CLAUDE_CODE_ENTRYPOINT']],
  ['cursor', ['CURSOR_TRACE_ID', 'CURSOR_AGENT']],
  [
    'codex',
    ['CODEX_SANDBOX', 'CODEX_SANDBOX_NETWORK_DISABLED', 'CODEX_THREAD_ID'],
  ],
];

export const detectCallerAgentsFromEnv = (
  env: NodeJS.ProcessEnv = process.env,
): CallerAgentKind[] =>
  callerAgentEvidenceFromEnv(env).map(({ agent }) => agent);

export const callerAgentEvidenceFromEnv = (
  env: NodeJS.ProcessEnv = process.env,
): Array<{ agent: CallerAgentKind; evidence: string[] }> =>
  ENV_MARKERS_BY_AGENT.map(([agent, markers]) => ({
    agent,
    evidence: markers.filter((marker) => nonEmpty(env[marker])),
  })).filter(({ evidence }) => evidence.length > 0);

export const detectCallerAgentFromEnv = (
  env: NodeJS.ProcessEnv = process.env,
): CallerAgentKind | undefined => detectCallerAgentsFromEnv(env)[0];

const CALLER_RUN_ID_HEX_LENGTH = 16;

const callerRunIdForSession = (session: string): string =>
  createHash('sha256')
    .update(session)
    .digest('hex')
    .slice(0, CALLER_RUN_ID_HEX_LENGTH);

export type CallerTelemetryFields = {
  callerAgent?: string;
  callerModel?: string;
  callerAgentSource?: 'handoff' | 'env';
  callerRunId?: string;
};

export const callerTelemetryFieldsFromArgs = (
  args: string[],
  env: NodeJS.ProcessEnv = process.env,
): CallerTelemetryFields => {
  const valueOf = (flag: string): string | undefined => {
    const index = args.indexOf(flag);
    return index !== -1 ? args[index + 1] : undefined;
  };
  const parsed = parseHandoff(
    {
      callerAgent: valueOf('--caller-agent'),
      callerModel: valueOf('--caller-model'),
      callerSession: valueOf('--caller-session'),
      handoffJson: valueOf('--handoff'),
    },
    env,
  );
  const handoff = parsed.ok ? parsed.handoff : null;
  const session =
    handoff?.session ??
    nonEmpty(env.CODEX_THREAD_ID) ??
    nonEmpty(env.CLAUDE_CODE_SESSION_ID);
  const callerRunId = session ? callerRunIdForSession(session) : undefined;
  const runId = callerRunId ? { callerRunId } : {};
  if (handoff) {
    return {
      callerAgent: handoff.agent,
      callerModel: handoff.model,
      callerAgentSource: 'handoff',
      ...runId,
    };
  }
  const detected = detectCallerAgentFromEnv(env);
  if (detected) {
    return { callerAgent: detected, callerAgentSource: 'env', ...runId };
  }
  return runId;
};

export const initiatorFor = (
  handoff: CallerHandoff | null,
): WorkItemInitiator =>
  handoff
    ? {
        kind: 'agent',
        agent: handoff.agent,
        ...(handoff.model ? { model: handoff.model } : {}),
      }
    : { kind: 'human' };
